<template><view class="page"><MeetingContentHeader title="嘉宾列表" :activity-id="activityId" /><view class="search"><input v-model="keyword" placeholder="搜索嘉宾姓名或机构" /></view><view v-if="loading" class="state">加载中...</view><view v-else class="list"><view v-for="item in filtered" :key="item.guestId" class="card"><image v-if="item.avatar" :src="item.avatar" mode="aspectFill" /><view><view class="title">{{ item.name }} <text v-if="item.englishName">{{ item.englishName }}</text></view><view class="sub">{{ [item.organization, item.title].filter(Boolean).join(' · ') }}</view><view v-if="item.introduction" class="intro">{{ item.introduction }}</view></view></view><view v-if="!filtered.length" class="state">暂无嘉宾</view></view></view></template>
<script setup>import { computed,ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';import MeetingContentHeader from '@/components/MeetingContentHeader.vue';import { getPortalGuests } from '@/api/portal/meeting';const activityId=ref(''),rows=ref([]),keyword=ref(''),loading=ref(true);const filtered=computed(()=>{const k=keyword.value.trim();return !k?rows.value:rows.value.filter(x=>`${x.name||''}${x.organization||''}${x.title||''}`.includes(k))});onLoad(o=>{activityId.value=o?.activityId||'';getPortalGuests(activityId.value).then(r=>rows.value=r.data||[]).finally(()=>loading.value=false)});</script><style scoped>.page{min-height:100vh;background:#f5f7fa}.search{padding:105rpx 24rpx 18rpx;background:#fff}.search input{padding:18rpx;border-radius:12rpx;background:#f5f7fa}.list{padding:20rpx 24rpx}.card{display:flex;gap:20rpx;padding:24rpx;margin-bottom:18rpx;background:#fff;border-radius:16rpx}.card image{width:96rpx;height:96rpx;border-radius:50%}.title{font-weight:600}.title text,.sub,.intro{color:#909399;font-size:24rpx}.sub,.intro{margin-top:8rpx}.state{padding:160rpx 24rpx;text-align:center;color:#909399}</style>
